    /**
     * Check if a package name is in the allowlist.
     *
     * @param packageName The package name to check
     * @return true if the package is allowed, false otherwise
     */
    public static boolean isPackageAllowed(String packageName) {
        if (packageName == null) {
            return false;
        }
        return ALLOWED_PACKAGES.contains(packageName);
    }

    /**
     * Get the total number of allowed packages.
     *
     * @return The count of allowed packages
     */
    public static int getAllowedPackageCount() {
        return ALLOWED_PACKAGES.size();
    }

    private PackageAllowlist() {
        // Utility class, no instantiation
    }
